<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="csrf-token" content="{{ csrf_token() }}"><title>@yield('title','EK-2 Sistemi')</title>
<style>
:root{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#172033;background:#f4f6f8}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1100px;margin:auto;padding:24px}.card{background:white;border:1px solid #e4e8ee;border-radius:14px;padding:20px;box-shadow:0 5px 18px rgba(0,0,0,.04)}input,select,button{font:inherit}input,select{width:100%;padding:12px;border:1px solid #cfd6df;border-radius:10px;background:#fff}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;padding:11px 16px;font-weight:700;cursor:pointer;background:#1f5eff;color:#fff;text-decoration:none}.btn.light{background:#e9eef7;color:#1b2940}.btn.danger{background:#b42318}.grid{display:grid;gap:16px}.grid3{grid-template-columns:repeat(4,1fr)}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #e8ecf1;text-align:left}.muted{color:#687386}.ok{padding:10px 12px;background:#e8f7ee;border-radius:10px;color:#176b37}.err{color:#b42318;font-size:.9rem}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.nav{display:flex;gap:10px;align-items:center}.mobile{max-width:520px;margin:auto}.mobile .btn{min-height:52px;width:100%;font-size:1.05rem}.step{display:none}.step.active{display:block}.camera-input{padding:16px;background:#f1f4f8;border:2px dashed #b6c0cc;border-radius:14px}.preview{width:100%;max-height:55vh;object-fit:contain;border-radius:12px;margin-top:12px;background:#111}.progress{height:6px;background:#e9edf2;border-radius:9px;overflow:hidden;margin-bottom:18px}.progress>div{height:100%;background:#1f5eff;width:20%;transition:.2s}.pagination{display:flex;flex-wrap:wrap;gap:6px;list-style:none;padding:0;margin:14px 0 0}.pagination li>*{display:block;padding:6px 11px;border:1px solid #e4e8ee;border-radius:8px;text-decoration:none}.pagination .active>*{background:#1f5eff;color:#fff}.pagination .disabled>*{color:#aab}@media(max-width:700px){.wrap{padding:14px}.grid3{grid-template-columns:1fr}table{font-size:.9rem}}
</style></head><body>@yield('body')
<script>
// Fotoğraf seçilince yatay çekildiyse uyar (EK-2 kâğıdı dikeydir); engellemez, doktor isterse devam eder
document.addEventListener('change',e=>{const i=e.target;if(i.type!=='file'||!i.files||!i.files[0])return;const u=URL.createObjectURL(i.files[0]),im=new Image();im.onload=()=>{let w=i.parentElement.querySelector('.yatay-uyari');if(im.naturalWidth>im.naturalHeight){if(!w){w=document.createElement('p');w.className='err yatay-uyari';i.parentElement.appendChild(w)}w.textContent='Fotoğraf yatay çekilmiş. Telefonu dik tutup kâğıdın tamamı görünecek şekilde yeniden çekmeniz önerilir.'}else if(w)w.remove();URL.revokeObjectURL(u)};im.src=u});
</script></body></html>
